public void processData() {
    Connection conn = null;
    try {
        conn = dataSource.getConnection();
        // Business logic here
    } catch (SQLException e) {
        logger.error("Database failure", e);
        throw new DataAccessException(e);
    } finally {
        if (conn != null) {
            try {
                conn.close();
            } catch (SQLException e) {
                logger.warn("Failed to close connection", e);
            }
        }
    }
}
